public static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
        while (bb.hasRemaining()) {
            byte b = bb.get();
            if ((b & 0x80) == 0) {
                sb.append((char) b);
            } else if ((b & 0xE0) == 0xC0) {
                if (!bb.hasRemaining()) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding");
                }
                byte b2 = bb.get();
                if ((b2 & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding");
                }
                sb.append((char) (((b & 0x1F) << 6) | (b2 & 0x3F)));
            } else if ((b & 0xF0) == 0xE0) {
                if (!bb.hasRemaining()) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding");
                }
                byte b2 = bb.get();
                if ((b2 & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding");
                }
                byte b3 = bb.get();
                if ((b3 & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding");
                }
                sb.append((char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F)));
            } else if ((b & 0xF8) == 0xF0) {
                if (!bb.hasRemaining()) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding");
                }
                byte b2 = bb.get();
                if ((b2 & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding");
                }
                byte b3 = bb.get();
                if ((b3 & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding");
                }
                byte b4 = bb.get();
                if ((b4 & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding");
                }
                sb.append((char) (((b & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F)));
            } else {
                throw new IllegalArgumentException("Invalid UTF-8 encoding");
            }
            i++;
        }
        return i;
    }

