public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    // Initialize a new IsomorphicGraphMapping object with the input graph
    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<V, E>(graph);

    // Define a method to check if two vertices are connected by an edge in the graph
    BiFunction<V, V, Boolean> areConnected = (v1, v2) -> graph.getEdges().stream()
            .anyMatch(edge -> edge.getFrom().equals(v1) && edge.getTo().equals(v2));

    // For each vertex in the graph, add the vertex and its corresponding edge to the IsomorphicGraphMapping object
    for (V vertex : graph.getVertices()) {
        // If the vertex is connected to any other vertex in the graph, add the edge to the mapping
        for (E edge : graph.getEdges()) {
            if (areConnected.apply(vertex, edge.getFrom())) {
                mapping.addEdge(vertex, edge);
            }
        }
    }

    // Return the IsomorphicGraphMapping object
    return mapping;
}

