@Override
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
	// Create a new graph
	Graph<V,E> graph = new Graph<>();

	// Add all the vertices
	for (String vertexLabel : resultMap.keySet()) {
		V vertex = resultMap.get(vertexLabel);
		graph.addVertex(vertex);
	}

	// Add all the edges
	for (String vertexLabel1 : resultMap.keySet()) {
		V vertex1 = resultMap.get(vertexLabel1);
		for (String vertexLabel2 : resultMap.keySet()) {
			V vertex2 = resultMap.get(vertexLabel2);
			if (!vertex1.equals(vertex2)) {
				E edge = new Edge(vertexLabel1, vertexLabel2);
				graph.addEdge(edge);
			}
		}
	}

	// Set the resulting graph
	target = graph;
}

