public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = ProtobufOutput.computeDelimitedSize(message, schema);
    int prefixSize = ProtobufOutput.computeRawVarint32Size(size);
    int totalSize = size + prefixSize;
    if (buffer.capacity() < totalSize) {
        buffer = LinkedBuffer.allocate(totalSize);
    }
    ProtobufOutput.writeRawVarint32(buffer, size);
    ProtobufOutput.writeDelimitedTo(buffer, message, schema);
    out.write(buffer.toByteArray(prefixSize, size - prefixSize));
    return size;
}

