protected void subAppend(LoggingEvent event) {
    // Check if the event is loggable
    if (!isAsSevereAsThreshold(event.getLevel())) {
        return;
    }

    // Determine the number of bytes to allocate
    int numBytes = event.getLoggerName().size();
    for (Object element : event.getParameters()) {
        numBytes += element.size();
    }

    // Allocate the bytes
    byte[] bytes = new byte[numBytes];
    int index = 0;

    // Write the logger name
    byte[] loggerNameBytes = event.getLoggerName().getBytes();
    for (int i = 0; i < loggerNameBytes.length; i++) {
        bytes[index++] = loggerNameBytes[i];
    }

    // Write the message
    byte[] messageBytes = event.getMessage().getBytes();
    for (int i = 0; i < messageBytes.length; i++) {
        bytes[index++] = messageBytes[i];
    }

    // Write the parameters
    for (Object parameter : event.getParameters()) {
        byte[] parameterBytes = parameter.toString().getBytes();
        for (int i = 0; i < parameterBytes.length; i++) {
            bytes[index++] = parameterBytes[i];
        }
    }

    // Write the timestamp
    byte[] timestampBytes = event.getTimestamp().toString().getBytes();
    for (int i = 0; i < timestampBytes.length; i++) {
        bytes[index++] = timestampBytes[i];
    }

    // Write the log level
    byte[] levelBytes = event.getLevel().toString().getBytes();
    for (int i = 0; i < levelBytes.length; i++) {
        bytes[index++] = levelBytes[i];
    }

    // Write the thread name
    byte[] threadNameBytes = event.getThreadName().getBytes();
    for (int i = 0; i < threadNameBytes.length; i++) {
        bytes[index++] = threadNameBytes[i];
    }

    // Write the exception
    if (event.getThrowableInformation() != null) {
        byte[] exceptionBytes = event.getThrowableInformation().toString().getBytes();
        for (int i = 0; i < exceptionBytes.length; i++) {
            bytes[index++] = exceptionBytes[i];
        }
    }

    // Flush the buffer
    buffer.flush();
}

public int addType(final String value) {
    // Check if the type table already contains a similar type
    Symbol symbol = typeTable.get(value);
    if (symbol != null) {
        // If the type table already contains a similar type, return its index
        return symbol.getIndex();
    }

    // Otherwise, create a new type Symbol and add it to the type table
    symbol = new TypeSymbol(value);
    typeTable.put(symbol.getValue(), symbol);
    return symbol.getIndex();
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
        // Check if the genericType is parameterized
        if (!(genericType instanceof ParameterizedType)) {
            return null;
        }

        // Get the type arguments for the genericType
        Type[] typeArguments = ((ParameterizedType) genericType).getActualTypeArguments();

        // Check if the type arguments are present
        if (typeArguments == null || typeArguments.length == 0) {
            return null;
        }

        // Resolve the type arguments using the type variable information for the targetType
        List<Class<?>> resolvedTypeArguments = new ArrayList<>();
        for (Type typeArgument : typeArguments) {
            if (typeArgument instanceof TypeVariable) {
                Type resolvedType = resolveTypeVariable((TypeVariable<?>) typeArgument, targetType);
                if (resolvedType != null) {
                    resolvedTypeArguments.add(resolvedType);
                }
            } else {
                resolvedTypeArguments.add(typeArgument);
            }
        }

        // Return the resolved type arguments
        return resolvedTypeArguments.toArray(new Class<?>[0]);
    }

public void accept(final Metrics data) {
    // Add the data to the existing cache
    cache.putAll(data.getMetrics());
    // Merge the metrics from the two caches
    for (String key : data.getMetrics().keySet()) {
        Metric existingMetric = cache.get(key);
        if (existingMetric == null) {
            cache.put(key, new Metric(key, data.getMetrics().get(key)));
        } else {
            Metric newMetric = data.getMetrics().get(key);
            Metric mergedMetric = mergeMetrics(existingMetric, newMetric);
            cache.put(key, mergedMetric);
        }
    }
}

