public Mappings diffStructure(String tableName, Mappings mappings) {
  if (tableName == null || mappings == null) {
    return null;
  }
  Mappings existingMappings = getMappings(tableName);
  if (existingMappings == null) {
    return null;
  }
  List<String> fields = new ArrayList<String>(mappings.getFields());
  for (String field : fields) {
    if (existingMappings.containsField(field)) {
      Mapping existingMapping = existingMappings.getMapping(field);
      if (existingMapping == null) {
        return null;
      }
      Mapping mapping = mappings.getMapping(field);
      if (mapping == null) {
        return null;
      }
      if (!existingMapping.equals(mapping)) {
        return null;
      }
    }
  }
  return null;
}

