public List<TimeRange> buildTimeRanges(long start, long end) {
  List<TimeRange> timeRanges = new ArrayList<>();
  while (start < end) {
    long timeRangeEnd = Math.min(start + FETCH_DATA_DURATION, end);
    timeRanges.add(new TimeRange(start, timeRangeEnd));
    start = timeRangeEnd + 1;
  }
  return timeRanges;
}

