public static long compressTimeBucket(long timeBucket, int dayStep) {
if (dayStep == 1) {
return timeBucket;
} else {
// Convert the timeBucket to a date
String dateString = Long.toString(timeBucket);
String formattedDateString = dateString.substring(0, 4) + "-" + dateString.substring(4, 6) + "-" + dateString.substring(6, 8);

// Parse the formatted date to a Date object
SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");
Date parsedDate = dateFormat.parse(formattedDateString);

// Calculate the start of the dayStep
Calendar calendar = Calendar.getInstance();
calendar.setTime(parsedDate);
calendar.set(Calendar.DATE, dayStep);
Date startOfDayStep = calendar.getTime();

// Re-format the startOfDayStep to the expected format
String reFormattedDateString = dateFormat.format(startOfDayStep);
reFormattedDateString = reFormattedDateString.replaceAll("-", "");

// Convert the re-formatted date string to a long value
return Long.parseLong(reFormattedDateString);
}
