@Override
    public Character convertToType(Class<?> type, Object value) throws Exception {
        if (type != Character.class) {
            throw new IllegalArgumentException("Invalid type for conversion: " + type);
        }
        if (value instanceof Character) {
            return (Character) value;
        } else if (value instanceof Integer) {
            return Character.toChars((Integer) value)[0];
        } else if (value instanceof Long) {
            return Character.toChars(((Long) value).intValue())[0];
        } else if (value instanceof Float) {
            return Character.toChars(((Float) value).intValue())[0];
        } else if (value instanceof Double) {
            return Character.toChars(((Double) value).intValue())[0];
        } else if (value instanceof String) {
            return ((String) value).charAt(0);
        } else {
            throw new IllegalArgumentException("Invalid input value for conversion: " + value);
        }
    }

