public JsonObject convertProperties(List<KeyStringValuePair> properties) {

    // Create a new JSON object to store the source data
    JsonObject sourceData = new JsonObject();

    // Loop through each property and convert it to JSON
    for (KeyStringValuePair property : properties) {
        String key = property.getKey();
        String value = property.getStringValue();
        // Check if the value is not null or empty
        if (value != null && !value.isEmpty()) {
            // Add the property to the source data JSON object
            sourceData.addProperty(key, value);
        }
    }

    return sourceData;
}

public int removeUnusedNodes(){
  Category rootNode = this.getRootNode();

  if(rootNode != null){
    int removedNodes = 0;

    List<Category> children = new ArrayList<Category>(rootNode.getChildren());

    for(Category child : children){
      if(child.isInactive()){
        rootNode.getChildren().remove(child);
        removedNodes++;
      }
      removedNodes += removeUnusedNodes(child);
    }

    return removedNodes;
  }

  return 0;
}

