	int stringLength = classFileBuffer.getShort(constantPoolEntryIndex);
	// Check if the buffer is large enough to hold the string
	if (charBuffer.length < stringLength) {
		throw new IllegalArgumentException("Buffer size is too small to hold the string");
	}
	// Read the string characters from the buffer
	for (int i = 0; i < stringLength; i++) {
