public boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    ListNode<E> curr = this.head;
    while (curr != null && curr != node) {
        curr = curr.next;
    }
    if (curr == node) {
        curr.prev.next = curr.next;
        curr.next.prev = curr.prev;
        curr.prev = null;
        curr.next = null;
        this.size--;
        return true;
    }
    return false;
}

