private List<Integer> computeUpperBounds(List<K> keys){
   // Initialize variables
   List<Integer> lowerBounds = new ArrayList<Integer>();
   for (K key : keys) {
      int lowerBound = Integer.MAX_VALUE;
      for (Integer round : key) {
         if (round < lowerBound) {
            lowerBound = round;
         }
      }
      lowerBounds.add(lowerBound);
   }
   return lowerBounds;
}

