public static String applyRelativePath(String path, String relativePath) {
    // Split the path and relativePath strings into lists of directories
    List<String> pathDirs = Arrays.asList(path.split("/"));
    List<String> relativePathDirs = Arrays.asList(relativePath.split("/"));

    // Remove the common prefix from the list of directories
    while (!pathDirs.isEmpty() && !relativePathDirs.isEmpty() && pathDirs.get(0).equals(relativePathDirs.get(0))) {
        pathDirs.remove(0);
        relativePathDirs.remove(0);
    }

    // Add the relativePath directories to the path
    for (String dir : relativePathDirs) {
        if (dir.equals("..")) {
            pathDirs.remove(pathDirs.size() - 1);
        } else {
            pathDirs.add(dir);
        }
    }

    // Join the pathDirs list into a single string
    return String.join("/", pathDirs);
}

