public Edge edgeToNext() {
    // Get the current node and the next node
    Node currentNode = getCurrentNode();
    Node nextNode = getNextNode();

    // Check if either of the nodes is virtual
    boolean currentNodeIsVirtual = currentNode instanceof VirtualNode;
    boolean nextNodeIsVirtual = nextNode instanceof VirtualNode;

    // Create the edge between the nodes
    Edge edge = new Edge();
    edge.setSource(currentNodeIsVirtual ? currentNode.getRealNode() : currentNode);
    edge.setTarget(nextNodeIsVirtual ? nextNode.getRealNode() : nextNode);

    return edge;
}

