    // If the size of the byte vector is less than the sum of the two byte values, enlarge it
    if (size < byteValue1 + byteValue2) {
        final byte[] newData = new byte[byteValue1 + byteValue2];
        System.arraycopy(data, 0, newData, 0, size);
        data = newData;
    }
    // Put the first byte into the byte vector
    data[size] = (byte) byteValue1;
    size++;
    // Put the second byte into the byte vector
    data[size] = (byte) byteValue2;
    size++;
    return this;
}

